  while(/^>([^\n\r]+)[\r\n]+([^>]*)/mg){$s{$1}=$2;$s{$1}=~s/[^A-Za-z]//g;$s{$1}=lc $s{$1};}
  END {
    for $k (keys %s){ printf "%s %d %s ... %s\n",$k,length($s{$k}),substr($s{$k},0,20),substr($s{$k},-20); }
