cat >/tmp/validate_primers.pl <<'PL'
use strict; use warnings;
my %s; my $name;
while (<>) { chomp; s/\r//g; if (/^>(\S+)/) { $name=$1; $s{$name}=''; } elsif (defined $name) { $s{$name}.=$_; } }
for (keys %s) { $s{$_}=lc $s{$_}; $s{$_}=~s/[^a-z]//g; }
sub rc { my $x=reverse shift; $x=~tr/acgt/tgca/; return $x; }
sub tm { my($x)=@_; my $v=`/tmp/primer3-pkg/root/usr/bin/oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $x`; chomp $v; return 0+$v; }
my $clamp='gcgtgc'; my $site='ggtctc'; my $spacer='a';
my %cfg=(
 input_fwd=>['input','fwd',688,18,'ggtt'], input_rev=>['input','rev',210,30,'atga'],
 egfp_fwd=>['egfp','fwd',4,19,'atga'], egfp_rev=>['egfp','rev',714,22,'ggta'],
 flag_fwd=>['flag','fwd',7,18,'ggta'], flag_rev=>['flag','rev',87,24,'gaca'],
 snap_fwd=>['snap','fwd',7,25,'gaca'], snap_rev=>['snap','rev',543,23,'ggtt'],
);
my %p; my $pn;
open my $fh,'<','primers.fasta' or die $!;
while(<$fh>){chomp;s/\r//g;if(/^>(\S+)/){$pn=$1;$p{$pn}=''}elsif(defined$pn){$p{$pn}.=lc$_}}
close $fh;
my $fail=0;
print "Primer checks\n";
for my $n (sort keys %cfg) {
 die "missing $n\n" unless exists $p{$n};
 my($k,$d,$pos,$len,$o)=@{$cfg{$n}};
 my $expected_anneal=$d eq'fwd'?substr($s{$k},$pos,$len):rc(substr($s{$k},$pos-$len,$len));
 my $tail=$clamp.$site.$spacer.$o;
 my $actual=substr($p{$n},length($tail));
 my $t=tm($actual);
 my $ok=length($actual)>=15&&length($actual)<=45&&$t>=58&&$t<=72&&$actual eq $expected_anneal&&$p{$n} eq $tail.$expected_anneal;
 $fail++ unless $ok;
 printf "%s anneal=%d nt Tm=%.3f fusion=%s %s\n",$n,length($actual),$t,uc$o,$ok?'PASS':'FAIL';
}
for my $k(qw(input egfp flag snap)) {
 my $x=$s{$k}; my @hits; while($x=~/(ggtctc|gagacc)/g){push @hits,uc$1.'@'.($-[0]+1)}
 print "$k source BsaI sites: ",@hits?join(',',@hits):'none',"\n";
 $fail++ if @hits;
}
for my $n (sort keys %p) {
 my $x=$p{$n}; my @h; while($x=~/(ggtctc|gagacc)/g){push @h,uc$1.'@'.($-[0]+1)}
 $fail++ unless @h==1&&$h[0]=~/^GGTCTC\@/;
 print "$n intentional site(s): ",join(',',@h),"\n";
}
for my $pair ([qw(input_fwd input_rev)],[qw(egfp_fwd egfp_rev)],[qw(flag_fwd flag_rev)],[qw(snap_fwd snap_rev)]) {
 my @t; for(@$pair){my($k,$d,$pos,$len,$o)=@{$cfg{$_}};my$tail=$clamp.$site.$spacer.$o;$t[push(@t,tm(substr($p{$_},length$tail)))-1]=0 if 0} # no-op
 my @tm; for(@$pair){my$tail=$clamp.$site.$spacer.$cfg{$_}[4];push @tm,tm(substr($p{$_},length$tail))}
 my$d=abs($tm[0]-$tm[1]);$fail++ if$d>5;printf "%s/%s delta=%.3f %s\n",@$pair,$d,$d<=5?'PASS':'FAIL';
}
# Construct the circular assembly at the GGTT junction and compare against output rotated to same point.
my $assembled=$cfg{input_fwd}[4].substr($s{input},688).substr($s{input},0,210).$cfg{input_rev}[4].substr($s{egfp},4,710).$cfg{egfp_rev}[4].substr($s{flag},7,80).$cfg{flag_rev}[4].substr($s{snap},7,536);
my $expected=substr($s{output},1548).substr($s{output},0,1548);
my $same=$assembled eq $expected; $fail++ unless $same; print "Circular assembly sequence: ",$same?'PASS':'FAIL'," (",length($assembled)," bp)\n";
# formatting
my @lines=do{open my$fh,'<','primers.fasta' or die$!;<$fh>};my $blank=grep{/^\s*$/}@lines;my $headers=grep{/^>/}@lines;print "FASTA formatting: ",(!$blank&&$headers==8)?'PASS':'FAIL'," (blank lines=$blank, headers=$headers)\n";$fail++ if$blank||$headers!=8;
print $fail ? "FAILURES=$fail\n" : "ALL CHECKS PASS\n";
exit($fail?1:0);
PL
